package com.refind.service.impl;
import com.refind.dao.UserDAO; import com.refind.exception.ValidationException; import com.refind.model.User; import com.refind.model.enums.Role; import com.refind.service.AuthService; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.NoSuchAlgorithmException; import java.time.LocalDateTime; import java.util.*;
public class JdbcAuthService implements AuthService { private final UserDAO dao; public JdbcAuthService(UserDAO dao){this.dao=dao;} public User register(String name,String email,String password){if(name==null||name.isBlank()||email==null||email.isBlank()||password==null||password.isBlank())throw new ValidationException("Name, email and password are required.");if(dao.findByEmail(email).isPresent())throw new ValidationException("Email is already registered.");User u=new User(name,email,hash(password),Role.USER,null);return dao.save(u);} public Optional<User> login(String email,String password){if(email==null||password==null)return Optional.empty();return dao.findByEmail(email).filter(u->MessageDigest.isEqual(u.getPasswordHash().getBytes(StandardCharsets.UTF_8),hash(password).getBytes(StandardCharsets.UTF_8)));} public boolean emailExists(String email){return dao.findByEmail(email).isPresent();} public void logout(){} private String hash(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v));return x.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
